package org.sleepwell.app;
import android.app.*;import android.content.*;import android.graphics.Rect;import android.os.*;import android.view.*;import android.view.inspector.WindowInspector;import android.widget.*;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.UiDevice;import org.junit.Test;import java.io.*;import java.util.concurrent.*;import static org.junit.Assert.*;
/** Actual native settings controls and private persisted state; all DND/expiry/permission effects are fake. */
public final class TrackingDndFlowTest {
 final Instrumentation i=InstrumentationRegistry.getInstrumentation();final Context c=i.getTargetContext();final UiDevice d=UiDevice.getInstance(i);TrackingDndFixture f;
 interface Task{void run()throws Exception;}interface Ready{boolean check()throws Exception;}
 void waitFor(Ready ready)throws Exception{long limit=SystemClock.elapsedRealtime()+10000;while(!ready.check()){if(SystemClock.elapsedRealtime()>limit)throw new AssertionError("DND fixture did not reach its expected state");Thread.sleep(30);}}
 View root(){for(View v:WindowInspector.getGlobalWindowViews())if(v.hasWindowFocus()&&v.isAttachedToWindow()&&v.getContext().getPackageName().equals(c.getPackageName()))return v;return null;}
 View find(View v,String label,boolean switches){if(v==null)return null;if((!switches||v instanceof Switch)&&(label.contentEquals(v.getContentDescription()==null?"":v.getContentDescription())||v instanceof TextView&&label.contentEquals(((TextView)v).getText())))return v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int n=0;n<g.getChildCount();n++){View found=find(g.getChildAt(n),label,switches);if(found!=null)return found;}}return null;}
 Rect control(String label,boolean switches){Rect[] result={null};i.runOnMainSync(()->{View v=find(root(),label,switches);while(v!=null&&!v.isClickable())v=v.getParent() instanceof View?(View)v.getParent():null;if(v==null||!v.isEnabled())return;Rect area=new Rect();if(v.getGlobalVisibleRect(area)&&area.height()==v.getHeight()&&area.width()==v.getWidth()&&v.getHeight()>=Design.dp(c,48)){int[] screen=new int[2];v.getLocationOnScreen(screen);result[0]=new Rect(screen[0],screen[1],screen[0]+v.getWidth(),screen[1]+v.getHeight());}else v.requestRectangleOnScreen(new Rect(0,0,v.getWidth(),v.getHeight()),false);});return result[0];}
 void click(String label)throws Exception{click(label,false);}void click(String label,boolean switches)throws Exception{waitFor(()->control(label,switches)!=null);View[] owner={null};CountDownLatch commit=new CountDownLatch(1);i.runOnMainSync(()->{owner[0]=root();assertNotNull(owner[0]);owner[0].getViewTreeObserver().registerFrameCommitCallback(commit::countDown);owner[0].invalidate();});assertTrue(commit.await(5,TimeUnit.SECONDS));Rect r=control(label,switches);assertNotNull(label,r);i.runOnMainSync(()->assertSame("Exact focused committed input owner",owner[0],root()));assertTrue(d.click(r.centerX(),r.centerY()));}
 void text(String label)throws Exception{waitFor(()->{boolean[] found={false};i.runOnMainSync(()->found[0]=find(root(),label,false)!=null);return found[0];});}
 File folder(){File f=new File(c.getExternalFilesDir(null),"verification");assertTrue(f.isDirectory()||f.mkdirs());return f;}
 void capture(String name,String label)throws Exception{text(label);CountDownLatch frame=new CountDownLatch(1);i.runOnMainSync(()->{View v=root();assertNotNull(v);v.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);v.invalidate();});assertTrue(frame.await(5,TimeUnit.SECONDS));assertTrue(d.takeScreenshot(new File(folder(),"tracking-dnd-"+name+".png")));}

 void ready()throws Exception{f.idle();waitFor(()->{boolean[] ok={false};i.runOnMainSync(()->ok[0]=f.resumed instanceof TrackingDndActivity&&((TrackingDndActivity)f.resumed).drawn==f.job().state&&root()!=null);return ok[0];});}
 void launch()throws Exception{f.launch();ready();}
 void recreate()throws Exception{Activity old=f.resumed;i.runOnMainSync(old::recreate);waitFor(()->f.resumed!=old&&f.resumed.hasWindowFocus());ready();}
 void run(Task task)throws Exception{try(TrackingDndFixture fixture=new TrackingDndFixture()){f=fixture;try{task.run();}catch(Exception|AssertionError failure){try{d.takeScreenshot(new File(folder(),"tracking-dnd-failure.png"));d.dumpWindowHierarchy(new File(folder(),"tracking-dnd-failure.xml"));}catch(Exception capture){failure.addSuppressed(capture);}throw failure;}}}
 @Test public void optInPermissionsSaveAndRecreationNeverActivateRule()throws Exception{run(()->{
  f.port.access=false;f.port.exact=false;launch();assertFalse(f.store().enabled());capture("default","Use during tracking");
  click("Open DND access");waitFor(()->f.policyOpens==1);assertEquals(1,f.policyOpens);
  click("Open expiry access");waitFor(()->f.expiryOpens==1);assertEquals(1,f.expiryOpens);capture("prerequisites","Expiry safeguard");
  click("Use during tracking",true);waitFor(()->{boolean[] checked={false};i.runOnMainSync(()->{View v=find(root(),"Use during tracking",true);checked[0]=v instanceof Switch&&((Switch)v).isChecked();});return checked[0];});
  click("Save tracking DND");waitFor(()->f.store().enabled());ready();assertTrue(f.store().enabled());assertEquals(0,f.port.on+f.port.sequence);
  recreate();capture("saved","Save tracking DND");assertTrue(f.store().enabled());
  f.port.access=true;f.port.exact=true;f.job().inspect();ready();capture("ready","Allowed by Android");assertEquals(0,f.port.on+f.port.sequence);
 });}
 @Test public void ownedRuleFailureAndRetryAreHonestAndPersisted()throws Exception{run(()->{TrackingDndRuntime.Job j=f.job();j.submit(()->{j.settings.enabled(true);j.owner.start("private-admitted-run",true,1000,1,()->true);},true);f.idle();launch();capture("owned","Rule requested for the admitted recording");TrackingDndLease lease=f.store().read();assertNotNull(lease);assertEquals(1,f.port.on);f.port.failOff=true;click("Turn off & clean up own rule");ready();assertEquals(lease.token,f.store().read().token);capture("cleanup-error","Fixture rule removal failed. Retry cleanup.");recreate();assertEquals(lease.token,f.store().read().token);assertFalse(f.store().enabled());f.port.failOff=false;click("Turn off & clean up own rule");ready();assertNull(f.store().read());assertEquals("",j.state.error);capture("cleaned","No SleepWell tracking rule held");assertTrue(f.port.rules.isEmpty());assertTrue(f.port.expiry.isEmpty());assertEquals(1,f.port.on);});}
}
